        "step_number": 3,
        "instruction": "Create a basic bar chart using ggplot2.",
        "code": "ggplot(data, aes(x = Category, y = Value)) +\n  geom_bar(stat = \"identity\", fill = \"steelblue\") +\n  labs(title = \"Bar Chart Example\", x = \"Category\", y = \"Value\") +\n  theme_minimal()"
