{
  "CAP_Theorem_Explanation": "The CAP theorem, also known as Brewer's theorem, states that in a distributed data store, it is impossible to simultaneously guarantee all three of the following: Consistency, Availability, and Partition Tolerance. A system can only ensure two out of these three guarantees at any given time.",
  "CAP_Theorem_Concepts": {
    "Consistency": "Every read receives the most recent write or an error. All nodes see the same data at the same time.",
    "Availability": "Every request receives a (non-error) response, without the guarantee that it contains the most recent write. The system remains operational at all times.",
    "Partition_Tolerance": "The system continues to operate despite arbitrary partitioning due to network failures. It can handle communication breakdowns between nodes."
  },
  "Examples": [
    {
      "System": "Cassandra",
      "Guarantees": ["Availability", "Partition Tolerance"],
      "Sacrifices": "Consistency",
      "Explanation": "Cassandra prioritizes Availability and Partition Tolerance, allowing for eventual consistency. This is ideal for large-scale distributed systems where uptime and partition resilience are crucial."
    },
    {
      "System": "MongoDB",
      "Guarantes": ["Consistency", "Availability"],
      "Sacrifices": "Partition Tolerance",
      "Explanation": "MongoDB in a single data center can be tuned for Consistency and Availability by avoiding network partitions. However, in the presence of partitions, it may sacrifice one of the other properties."
    },
    {
      "System": "etcd",
      "Guarantees": ["Consistency", "Partition Tolerance"],
      "Sacrifices": "Availability",
      "Explanation": "etcd, used in Kubernetes, prioritizes Consistency and Partition Tolerance. If a network partition occurs, it may become unavailable until the partition is resolved."
    }
  ]
}
