Provide a JavaScript snippet to debounce a search input with a 300ms delay.

```javascript
// Debounce function
function debounce(func, delay) {
  let timer;
  return function (...args) {
    const context = this;
    clearTimeout(timer);
    timer = setTimeout(() => func.apply(context, args), delay);
  };
}

// Example usage with a search input
const searchInput = document.getElementById('search');

searchInput.addEventListener(
  'input',
  debounce(function (e) {
    console.log('Searching for:', e.target.value);
    // Perform your search logic here
  }, 300)
);
```

Provide a C# example using HttpClient to make a GET request and parse JSON.

```
using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Text.Json;

class Program
{
    static async Task Main(string[] args)
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                // Make a GET request to a sample JSON API
                HttpResponseMessage response = await client.GetAsync("https://jsonplaceholder.typicode.com/posts/1");

                // Ensure the request was successful
                response.EnsureSuccessStatusCode();

                // Read the JSON content as a string
                string json = await response.Content.ReadAsStringAsync();

                // Parse the JSON into a dynamic object
                var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
                var post = JsonSerializer.Deserialize<Post>(json, options);

                // Display the parsed data
                Console.WriteLine($"Post ID: {post.Id}");
                Console.WriteLine($"User ID: {post.UserId}");
                Console.WriteLine($"Title: {post.Title}");
                Console.WriteLine($"Body: {post.Body}");
            }
            catch (HttpRequestException e)
            {
                Console.WriteLine($"Request error: {e.Message}");
            }
        }
    }
}

// Class to represent the structure of the JSON response
public class Post
{
    public int Id { get; set; }
    public int UserId { get; set; }
    public string Title { get; set; }
    public string Body { get; set; }
}
